const RAW = [38, 22, 17, 15, 13, 11];
const SCALE = [12, 14, 16, 20, 24, 32, 48, 64];
const out = RAW.filter((v) => !SCALE.includes(v)).length;   // 칸 밖 개수

const snap = (v) => { let b = SCALE[0], bd = 1e9;
  SCALE.forEach((s) => { const d = Math.abs(v - s); if (d < bd || (d === bd && s > b)) { b = s; bd = d; } });
  return b; };
